import pytest
from candidate import find_zero, poly


class TestFindZero:
    def test_find_zero_linear_simple(self):
        result = find_zero([1, 2])
        assert abs(result - (-0.5)) < 1e-6

    def test_find_zero_linear_negative_root(self):
        result = find_zero([-1, 3])
        assert abs(result - (-1/3)) < 1e-6

    def test_find_zero_cubic_polynomial(self):
        result = find_zero([-6, 11, -6, 1])
        roots = [1.0, 2.0, 3.0]
        assert any(abs(result - r) < 1e-4 for r in roots)

    def test_find_zero_quadratic_roots_at_1_and_2(self):
        result = find_zero([1, -3, 2])
        assert (abs(result - 1.0) < 1e-4 or abs(result - 2.0) < 1e-4)

    def test_find_zero_root_at_zero(self):
        result = find_zero([0, 1])
        assert abs(result) < 1e-6

    def test_find_zero_root_at_one(self):
        result = find_zero([-1, 1])
        assert abs(result - 1.0) < 1e-6

    def test_find_zero_root_at_negative_one(self):
        result = find_zero([1, 1])
        assert abs(result - (-1.0)) < 1e-6

    def test_find_zero_quadratic_with_two_roots(self):
        result = find_zero([10, -30, 20])
        assert (abs(result - 1.0) < 1e-4 or abs(result - 0.5) < 1e-4)

    def test_find_zero_large_coefficients(self):
        result = find_zero([1000, 2000])
        assert abs(result - (-0.5)) < 1e-6

    def test_find_zero_small_coefficients(self):
        result = find_zero([0.001, 0.002])
        assert abs(result - (-0.5)) < 1e-6

    def test_find_zero_high_degree_polynomial(self):
        result = find_zero([1, 0, -1])
        assert (abs(result - 1.0) < 1e-4 or abs(result - (-1.0)) < 1e-4)

    def test_find_zero_returns_float(self):
        result = find_zero([1, 2])
        assert isinstance(result, float)

    def test_find_zero_with_none_raises_error(self):
        with pytest.raises((TypeError, AttributeError)):
            find_zero(None)

    def test_find_zero_with_empty_list(self):
        result = find_zero([])
        assert abs(result) < 1e-6

    def test_find_zero_with_single_zero_coefficient(self):
        result = find_zero([0])
        assert abs(result) < 1e-6

    def test_find_zero_result_is_zero_of_polynomial(self):
        xs = [-6, 11, -6, 1]
        result = find_zero(xs)
        assert abs(poly(xs, result)) < 1e-4

    def test_find_zero_result_zero_for_quadratic(self):
        xs = [1, -3, 2]
        result = find_zero(xs)
        assert abs(poly(xs, result)) < 1e-4

    def test_find_zero_precision_linear(self):
        result = find_zero([1, 2])
        assert abs(result - (-0.5)) < 1e-8

    def test_find_zero_with_float_coefficients(self):
        result = find_zero([0.5, 1.5])
        assert abs(result - (-1/3)) < 1e-6

    def test_find_zero_negative_and_positive_coefficients(self):
        result = find_zero([-5, 3])
        assert abs(result - (5/3)) < 1e-6

    def test_find_zero_polynomial_with_repeated_root(self):
        result = find_zero([0, 0, 1])
        assert abs(result) < 1e-4

    def test_poly_helper_evaluates_correctly(self):
        assert poly([1, 2, 3], 0) == 1
        assert poly([1, 2, 3], 1) == 6
        assert poly([1, 2, 3], 2) == 15

    def test_find_zero_converges_for_wide_root(self):
        result = find_zero([1, 100])
        assert abs(result - (-0.01)) < 1e-6

    def test_find_zero_converges_for_large_root(self):
        result = find_zero([100, 1])
        assert abs(result - (-100)) < 1e-2
